Given a number n, find all 1 to n bit numbers with no consecutive 1's in their binary representation.  Examples:Input: n = 3Output: [1, 2, 4, 5]Explanation: The binary representations of the numbers from 1 to 7 are 1, 10, 11, 100, 101, 110, and 111. Among these, 3 (11), 6 (110), and 7 (111) contain consecutive 1's.Input: n = 2Output: [1, 2]Explanation: The binary representations of the numbers from 1 to 3 are 1, 10, and 11. Among these, 3 (11) contains consecutive 1's in its binary representation.Try It YourselfTable of Content[Naive Approach] Brute Force Check - O(2ⁿ × n) Time and O(2ⁿ) Space[Expected Approach] DFS with Constraint - O(2ⁿ) Time and O(2ⁿ) Space[Naive Approach] Brute Force Check - O(2ⁿ × n) Time and O(2ⁿ) SpaceGenerate all n-bit numbers from 0 to 2n - 1. Check each number for consecutive 1's by scanning bits. 
            C++

    #include <vector>
#include <iostream>
using namespace std;

// Checks whether a number has consecutive 1's
bool isValid(int num) {
    while (num > 0) {
        if ((num & 1) && (num & 2))
            return false;
        num >>= 1;
    }
    return true;
}

// Returns all n-bit numbers having no consecutive 1's
vector<int> noConsecutiveOnes(int n) {
    vector<int> ans;

    // Check every n-bit number
    for (int num = 0; num < (1 << n); num++) {
        if (isValid(num))
            ans.push_back(num);
    }

    // Remove 0 if only positive numbers are required
    ans.erase(remove(ans.begin(), ans.end(), 0), ans.end());

    return ans;
}

int main() {
    int n = 3;

    vector<int> ans = noConsecutiveOnes(n);

    for (int x : ans)
        cout << x << " ";

    return 0;
}


